// ── WF7: Decodificar y validar CSV enviado desde la web ───────────────────
const { csv_base64, filename } = $json.body || $json;
if (!csv_base64) return [{ json: { ok: false, error: 'Falta campo csv_base64' } }];

let csvContent;
try { csvContent = Buffer.from(csv_base64, 'base64').toString('utf-8'); }
catch(e) { return [{ json: { ok: false, error: 'csv_base64 inválido: ' + e.message } }]; }

const allLines = csvContent.trim().split('\n').filter(l => l.trim());
if (allLines.length < 2) return [{ json: { ok: false, error: 'CSV vacío o sin filas de datos' } }];

const headers = allLines[0].split(',').map(h => h.trim().replace(/^"|"$/g,'').toLowerCase());
const required = ['student_id','student_name','course_id','date','status'];
const missing = required.filter(f => !headers.includes(f));
if (missing.length > 0) return [{ json: { ok: false, error: 'Campos faltantes: ' + missing.join(', ') } }];

const validStatuses = ['present','absent','late','excused'];
const records = [], errors = [];
for (let i = 1; i < allLines.length; i++) {
  const values = allLines[i].split(',').map(v => v.trim().replace(/^"|"$/g,''));
  const row = {};
  headers.forEach((h, idx) => { row[h] = values[idx]||''; });
  const errs = [];
  if (!row.student_id)   errs.push('Fila '+(i+1)+': student_id vacío');
  if (!row.student_name) errs.push('Fila '+(i+1)+': student_name vacío');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(row.date)) errs.push('Fila '+(i+1)+': fecha inválida ('+row.date+')');
  if (!validStatuses.includes(row.status)) errs.push('Fila '+(i+1)+': status inválido ('+row.status+')');
  if (errs.length > 0) errors.push(...errs);
  else records.push(row);
}
if (records.length === 0) return [{ json: { ok: false, error: 'Sin registros válidos. Detalles: ' + errors.slice(0,3).join('; ') } }];

const safe = s => String(s||'').replace(/'/g,"''");
const valueRows = records.map(r =>
  "('" + safe(r.student_id) + "','" + safe(r.student_name) + "','" +
  safe(r.course_id) + "','" + safe(r.date) + "','" + safe(r.status) + "')"
);
const sql_query = 'INSERT INTO attendance (student_id, student_name, course_id, date, status) VALUES\n' +
  valueRows.join(',\n') + '\nON CONFLICT DO NOTHING';

const cnt = {
  present: records.filter(r=>r.status==='present').length,
  absent:  records.filter(r=>r.status==='absent').length,
  late:    records.filter(r=>r.status==='late').length,
  excused: records.filter(r=>r.status==='excused').length
};
return [{ json: { ok: true, sql_query, records, insertCount: records.length, errorCount: errors.length, errors, stats: cnt, filename: filename||'upload.csv' } }];

// ── WF7: Preparar respuesta final ────────────────────────────────────────
const orig = $('Procesar CSV Web').first().json;
const dateStr = new Date().toISOString().split('T')[0];
const safe = s => String(s||'').replace(/'/g,"''");
const rpt_sql = "INSERT INTO reports (report_type, file_path, status, records_count) VALUES ('attendance_web', '/data/shared/output/web_upload_" + dateStr + ".html', 'generated', " + (orig.insertCount||0) + ")";
return [{
  json: {
    ok: true,
    message: orig.insertCount + ' registros de asistencia procesados correctamente.',
    inserted: orig.insertCount,
    skipped_errors: orig.errorCount,
    error_details: orig.errors || [],
    stats: orig.stats,
    filename: orig.filename,
    rpt_sql
  }
}];
